+import { createHmac, timingSafeEqual } from 'node:crypto';
 import { Router } from 'express';
 import { updateShipmentStatus } from '../shipments/service';

 export const courierWebhook = Router();

+function validSignature(raw: Buffer, header: string | undefined): boolean {
+  if (!header) return false;
+  const expected = createHmac('sha256', process.env.COURIER_WEBHOOK_SECRET ?? '')
+    .update(raw)
+    .digest('hex');
+  const a = Buffer.from(expected);
+  const b = Buffer.from(header);
+  return a.length === b.length && timingSafeEqual(a, b);
+}
+
 courierWebhook.post('/courier/events', async (req, res) => {
+  if (!validSignature(req.body as Buffer, req.get('X-Courier-Signature'))) {
+    return res.status(401).end();
+  }
   const event = JSON.parse((req.body as Buffer).toString('utf8'));
   await updateShipmentStatus(event.trackingCode, event.status);
   res.status(204).end();
 });

